import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.config.IConfigSpec;
import net.minecraftforge.fml.config.ModConfig;

@Mod(value="aoi_assistant")
public final class AoiAssistantMod {
    public static final String ID = "aoi_assistant";

    public AoiAssistantMod() {
        ModLoadingContext.get().registerConfig(ModConfig.Type.CLIENT, (IConfigSpec)AssistantConfig.SPEC);
    }
}

