    private static void showSources(String arg) {
        if (!ChatController.get().service.view().loggedIn()) {
            ChatCommands.ready();
            return;
        }
        int index = arg.isBlank() ? sources.latestIndex() : Integer.parseInt(arg);
        Models.Message m = sources.get(index);
        if (m == null) {
            ChatCommands.say("這則來源已不在本機暫存；請查看網站對話紀錄。");
            return;
        }
        if (m.facts().isEmpty()) {
            ChatCommands.say("這則回答沒有提供來源。");
            return;
        }
        int count = 0;
        for (JsonElement item : m.facts()) {
            if (count++ >= 12) break;
            if (item.isJsonObject()) {
                String source;
                JsonObject f = item.getAsJsonObject();
                ChatCommands.say(Models.text(f, "playerTitle", Models.text(f, "title", "來源")));
                String summary = Models.text(f, "playerSummary", Models.text(f, "text", ""));
                if (!summary.isBlank()) {
                    ChatCommands.say(Models.safe(summary, 2400));
                }
                if (!(source = Models.text(f, "source", "")).isBlank()) {
                    ChatCommands.say("依據：" + Models.safe(source, 600));
                }
                if (!summary.isBlank() || !source.isBlank()) continue;
                ChatCommands.say(Models.safe(item.toString(), 1200));
                continue;
            }
            ChatCommands.say(Models.safe(item.toString(), 1200));
        }
    }

    private ChatCommands() {
    }

    static {
        HANDLER = new CommandRoutes.Handler(){

            @Override
            public void question(String q) {
                ChatCommands.ask(q);
            }

            @Override
            public void action(CommandRoutes.Action a, String arg) {
                ChatCommands.handle(a, arg);
            }
        };
        local = new CommandDispatcher();
        CommandRoutes.register(local, HANDLER);
    }

    private record Deletion(String token, String owner, String conversation, String message, long expires) {
    }
