package io.github.coyotewolf.aoi.client.commands;

import io.github.coyotewolf.aoi.client.commands.CommandRoutes;
import java.util.function.Consumer;

public final class ImeCommandPolicy {
    private String lastText = "";
    private int lastCaret = -1;
    private boolean owned;

    public void update(String text, int caret, boolean disabledInCommands, Consumer<Boolean> editing) {
        boolean ai;
        boolean bl = ai = disabledInCommands && CommandRoutes.owns(text);
        if (!(!ai || this.owned && this.lastText.equals(text) && this.lastCaret == caret)) {
            editing.accept(true);
        } else if (this.owned && !ai) {
            editing.accept(!disabledInCommands || !text.stripLeading().startsWith("/"));
        }
        this.owned = ai;
        this.lastText = text;
        this.lastCaret = caret;
    }

    public void reset() {
        this.owned = false;
        this.lastText = "";
        this.lastCaret = -1;
    }
}

