package io.github.coyotewolf.aoi.client.commands;

import io.github.coyotewolf.aoi.model.Models;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ReplySources {
    private String conversation = "";
    private int next = 1;
    private int latest;
    private final LinkedHashMap<Integer, Models.Message> rows = new LinkedHashMap();

    public void clear() {
        this.rows.clear();
        this.conversation = "";
        this.next = 1;
        this.latest = 0;
    }

    public void sync(String cid, List<Models.Message> messages) {
        if (!this.conversation.equals(cid)) {
            this.clear();
            this.conversation = cid;
        }
        List<Models.Message> all = messages.stream().filter(m -> m.role().equals("assistant")).toList();
        List<Models.Message> selected = all.subList(Math.max(0, all.size() - 64), all.size());
        HashSet<String> ids = new HashSet<String>();
        for (Models.Message m2 : selected) {
            if (!m2.role().equals("assistant")) continue;
            ids.add(m2.id());
        }
        this.rows.entrySet().removeIf(e -> !ids.contains(((Models.Message)e.getValue()).id()));
        this.latest = 0;
        for (Models.Message m2 : selected) {
            if (!m2.role().equals("assistant")) continue;
            Integer key = this.rows.entrySet().stream().filter(e -> ((Models.Message)e.getValue()).id().equals(m2.id())).map(Map.Entry::getKey).findFirst().orElse(null);
            if (key == null) {
                key = this.next++;
            }
            this.rows.put(key, m2);
            this.latest = key;
            while (this.rows.size() > 64) {
                this.rows.remove(this.rows.keySet().iterator().next());
            }
        }
    }

    public Models.Message get(int index) {
        return this.rows.get(index);
    }

    public int latestIndex() {
        return this.latest;
    }
}

