import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraftforge.registries.ForgeRegistries;

public final class NearbyEntities {
    public static String find(NearbyQuery query) {
        String scope;
        Minecraft mc = Minecraft.m_91087_();
        if (!mc.m_18695_()) {
            throw new IllegalStateException("須在遊戲主執行緒搜尋。");
        }
        if (mc.f_91074_ == null || mc.f_91073_ == null) {
            return "請進入世界後搜尋附近實體。";
        }
        ArrayList<NearbySearch.Candidate> candidates = new ArrayList<NearbySearch.Candidate>();
        for (String[] entity : mc.f_91073_.m_104735_()) {
            ResourceLocation key;
            if (entity == mc.f_91074_ || !entity.m_6084_() || entity.m_213877_() || (key = ForgeRegistries.ENTITY_TYPES.getKey((Object)entity.m_6095_())) == null) continue;
            Object extra = entity.m_6095_().m_20676_().getString();
            if (entity instanceof ItemEntity) {
                ItemEntity item = (ItemEntity)entity;
                ResourceLocation itemId = ForgeRegistries.ITEMS.getKey((Object)item.m_32055_().m_41720_());
                extra = (String)extra + " " + item.m_32055_().m_41786_().getString() + " " + String.valueOf(itemId);
            }
            candidates.add(new NearbySearch.Candidate(key.toString(), Models.safe(entity.m_7755_().getString(), 80), Models.safe((String)extra, 200), entity.m_20185_(), entity.m_20186_(), entity.m_20189_()));
        }
        ArrayList<String> terms = new ArrayList<String>();
        for (String term : query.query().split("[,，、]")) {
            ArrayList<String> exact = new ArrayList<String>();
            for (EntityType type : ForgeRegistries.ENTITY_TYPES.getValues()) {
                ResourceLocation key;
                if (!type.m_20676_().getString().equalsIgnoreCase(term.strip()) || (key = ForgeRegistries.ENTITY_TYPES.getKey((Object)type)) == null) continue;
                exact.add(key.toString());
            }
            if (exact.isEmpty()) {
                terms.add(term.strip());
                continue;
            }
            terms.addAll(exact);
        }
        NearbyQuery resolved = new NearbyQuery(String.join((CharSequence)",", terms), query.radius());
        List<NearbySearch.Found> found = NearbySearch.search(resolved, mc.f_91074_.m_20185_(), mc.f_91074_.m_20186_(), mc.f_91074_.m_20189_(), candidates);
        String string = scope = query.radius() == 0 ? "玩家中心的全部已載入實體" : "以你為中心、半徑" + query.radius() + "格內的已載入實體";
        if (found.isEmpty()) {
            return "在" + scope + "中沒有找到「" + Models.safe(query.query(), 160) + "」。這不代表未載入區域或伺服器沒有牠；可移動後再問，或改用完整實體ID。";
        }
        NearbySearch.Found nearest = found.get(0);
        NearbySearch.Candidate e = nearest.entity();
        String height = Math.abs(nearest.dy()) < 1.0 ? "高度與你相近" : (nearest.dy() > 0.0 ? "比你高" : "比你低") + Math.round(Math.abs(nearest.dy())) + "格";
        return "最近的「" + e.name() + "」在你的" + NearbySearch.direction(nearest.dx(), nearest.dz()) + "，直線距離約" + Math.round(nearest.distance()) + "格，" + height + "。座標：X " + (int)Math.floor(e.x()) + "，Y " + (int)Math.floor(e.y()) + "，Z " + (int)Math.floor(e.z()) + "。\n搜尋範圍：" + scope + "；共找到" + found.size() + "個符合項目，不受視野或牆壁遮擋限制，仍受伺服器實體追蹤範圍限制。";
    }

    public static String fromAi(NearbyQuery query) {
        Minecraft mc = Minecraft.m_91087_();
        ClientLevel level = mc.f_91073_;
        LocalPlayer player = mc.f_91074_;
        try {
            return (String)mc.m_18691_(() -> {
                if (mc.f_91073_ != level || mc.f_91074_ != player) {
                    throw new IllegalStateException("世界已切換，請重新搜尋。");
                }
                return NearbyEntities.find(query);
            }).get(10L, TimeUnit.SECONDS);
        }
        catch (Exception e) {
            throw new IllegalStateException("無法完成本機搜尋，請重新提問。", e);
        }
    }

    private NearbyEntities() {
    }
}

