import java.util.LinkedHashSet;
import java.util.List;
import java.util.UUID;

public final class AnnouncementPolicy {
    private final LinkedHashSet<String> seen = new LinkedHashSet();
    private int failures;

    public static List<Notice> parse(JsonElement json) {
        JsonObject root = json.getAsJsonObject();
        if (root.get("version").getAsInt() != 1) {
            throw new IllegalArgumentException("version");
        }
        JsonArray rows = root.getAsJsonArray("announcements");
        if (rows.size() > 20) {
            throw new IllegalArgumentException("count");
        }
        ArrayList<Notice> result = new ArrayList<Notice>();
        HashSet<String> ids = new HashSet<String>();
        for (JsonElement row : rows) {
            JsonObject n = row.getAsJsonObject();
            String id = n.get("id").getAsString();
            if (!UUID.fromString(id).toString().equals(id) || !ids.add(id)) {
                throw new IllegalArgumentException("id");
            }
            String title = AnnouncementPolicy.text(n.get("title"), 80, false);
            String body = AnnouncementPolicy.text(n.get("body"), 500, true);
            Instant expiry = Instant.parse(n.get("expires_at").getAsString());
            result.add(new Notice(id, title, body, expiry));
        }
        return List.copyOf(result);
    }

