package io.github.coyotewolf.aoi.model;

import com.google.gson.JsonObject;
import java.util.Set;

public record BiomeResult(String id, String name, String dimension, int x, int y, int z) {
    public String format() {
        return "目前生態域：" + (this.name == null || this.name.isBlank() ? this.id : this.name) + "\n完整 ID：" + this.id + "\n維度：" + this.dimension + "；位置：X " + this.x + "，Y " + this.y + "，Z " + this.z + "。\n以玩家所在位置（含高度）讀取；地下與地表可能是不同生態域。";
    }

    public static void validateAction(JsonObject o) {
        if (!(o.keySet().equals(Set.of("version", "type")) && o.get("version").isJsonPrimitive() && o.getAsJsonPrimitive("version").isNumber() && o.get("version").getAsDouble() == 1.0 && o.get("type").isJsonPrimitive() && o.getAsJsonPrimitive("type").isString() && o.get("type").getAsString().equals("current_biome"))) {
            throw new IllegalArgumentException("生態域查詢格式無效。");
        }
    }
}

